// Cria o dono que este teste vai apagar e conta os donos depois disso
const base = pm.environment.get("baseUrl");
const owner = {
  firstName: "Clara",
  lastName: "Lima",
  address: "Rua do Sol, 30",
  city: "Olinda",
  telephone: "8199990009"
};

pm.sendRequest({
  url: base + "/owners",
  method: "POST",
  header: { "Content-Type": "application/json" },
  body: { mode: "raw", raw: JSON.stringify(owner) }
}, (err, res) => {
  if (err) throw err;
  if (res.code !== 201) throw new Error("Preparação falhou: POST do dono devolveu " + res.code);
  pm.collectionVariables.set("deleteOwnerId", res.json().id);

  pm.sendRequest(base + "/owners", (listErr, listRes) => {
    if (listErr) throw listErr;
    pm.collectionVariables.set("ownersCountBefore", listRes.json().length);
  });
});

const base = pm.environment.get("baseUrl");
const ownerId = Number(pm.collectionVariables.get("deleteOwnerId"));
const countBefore = Number(pm.collectionVariables.get("ownersCountBefore"));

// Aqui 404 é falha: o dono acabou de ser criado e tem de ser apagado de verdade
pm.test("status 204", () => pm.response.to.have.status(204));

pm.test("responde em menos de 500 ms", () => {
  pm.expect(pm.response.responseTime).to.be.below(500);
});

