// Cria tipo, dono, pet e visita deste teste e guarda os totais depois disso
const base = pm.environment.get("baseUrl");

function post(path, data, next) {
  pm.sendRequest({
    url: base + path,
    method: "POST",
    header: { "Content-Type": "application/json" },
    body: { mode: "raw", raw: JSON.stringify(data) }
  }, (err, res) => {
    if (err) throw err;
    if (res.code !== 201) throw new Error("Preparação falhou: POST " + path + " devolveu " + res.code);
    next(res.json());
  });
}

function saveCounts(resources, counts) {
  if (resources.length === 0) {
    pm.collectionVariables.set("cascadeCountsBefore", JSON.stringify(counts));
    return;
  }
  pm.sendRequest(base + "/" + resources[0], (err, res) => {
    if (err) throw err;
    counts[resources[0]] = res.json().length;
    saveCounts(resources.slice(1), counts);
  });
}

